<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'assistant', false);
 start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='assistant'){header('Location: ../auth/login.php');exit;}$q=trim($_GET['q']??'');$sql="SELECT c.id,c.patient_id,c.dentist_id,c.created_role,COALESCE(c.chart_date,DATE(c.created_at)) chart_date,u.first_name,u.last_name,u.email,COUNT(t.id) marked_teeth,COALESCE(cr.first_name,'Clinic') creator_first,COALESCE(cr.last_name,'Staff') creator_last FROM dental_charts c JOIN users u ON u.id=c.patient_id LEFT JOIN dental_chart_teeth t ON t.chart_id=c.id LEFT JOIN users cr ON cr.id=COALESCE(c.created_by,c.dentist_id)";$params=[];$types='';if($q!==''){$sql.=" WHERE u.first_name LIKE ? OR u.last_name LIKE ? OR u.email LIKE ?";$like='%'.$q.'%';$params=[$like,$like,$like];$types='sss';}$sql.=' GROUP BY c.id ORDER BY chart_date DESC,c.id DESC';$st=$conn->prepare($sql);if($types)$st->bind_param($types,...$params);$st->execute();$charts=$st->get_result();require '../includes/ui.php';ui_header('Chart Records','assistant');ui_sidebar('assistant','charts.php');?>
<div class="page-head"><div><div class="eyebrow">DENTAL CHARTS</div><h1>Chart Records</h1><div class="muted">Prepare 3D dental charts for clinical review.</div></div><a class="btn btn-primary" href="chart_editor.php">Create Chart</a></div><?php if(isset($_GET['locked']))flash('error','That chart was confirmed by a dentist. Only a dentist can change it now.');if(isset($_GET['saved']))flash('success','Chart saved. The dentists were notified to review it.');?><section class="card"><form class="directory-search"><input name="q" value="<?=e($q)?>" placeholder="Search patient or email"><button class="btn btn-primary">Search</button><?php if($q):?><a class="btn btn-secondary" href="charts.php">Clear</a><?php endif;?></form></section><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Date</th><th>Marked Teeth</th><th>Created By</th><th>Action</th></tr></thead><tbody><?php if(!$charts->num_rows):?><tr><td colspan="5" class="empty">No dental charts yet.</td></tr><?php endif;?><?php while($c=$charts->fetch_assoc()):?><tr><td><b><?=e($c['first_name'].' '.$c['last_name'])?></b><br><small class="muted"><?=e($c['email'])?></small></td><td><?=e(date('M d, Y',strtotime($c['chart_date'])))?></td><td><span class="badge"><?=$c['marked_teeth']?> marked</span></td><td><?=e($c['creator_first'].' '.$c['creator_last'])?></td><td><?php if(($c['created_role']??'')==='assistant'&&empty($c['dentist_id'])):?><a class="btn btn-secondary" href="chart_editor.php?id=<?=$c['id']?>">Edit Chart</a><?php else:?><span class="badge">Confirmed by dentist</span><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></section><?php $st->close();ui_footer();?>
